(2532824, 348469, 32030, '<td valign="top">What an interesting tree.  I like the angle. 8</td>', 'What an interesting tree.  I like the angle. 8', '2006-06-20 20:06:30.000000', NULL, 1),
(2532828, 348835, 42100, '<td valign="top">One of my top three picks for the challenge, I guess that would make it my top pick of the GTG.  Love the haze in the valleys.  Excellent!</td>', 'One of my top three picks for the challenge, I guess that would make it my top pick of the GTG.  Love the haze in the valleys.  Excellent!', '2006-06-20 20:07:30.000000', NULL, 1),
(2532830, 348171, 32030, '<td valign="top">IMHO a bit too much forground...but I seem to be saying that a lot...so maybe it is just me.  I wish the shadows were on the subjects back and that we could see the face a bit better. 8</td>', 'IMHO a bit too much forground...but I seem to be saying that a lot...so maybe it is just me.  I wish the shadows were on the subjects back and that we could see the face a bit better. 8', '2006-06-20 20:08:02.000000', NULL, 1),
(2532831, 349282, 32030, '<td valign="top">Poor puppy!  Looks just a tad blueish to me. 7</td>', 'Poor puppy!  Looks just a tad blueish to me. 7', '2006-06-20 20:08:38.000000', NULL, 1),
