INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2544199, 349051, 27133, '<td valign="top">Oh this is a sad sight indeed.</td>', 'Oh this is a sad sight indeed.', '2006-06-23 07:02:41.000000', NULL, 1),
(2544200, 349055, 27133, '<td valign="top">Wonderful work.</td>', 'Wonderful work.', '2006-06-23 07:04:09.000000', NULL, 1),
(2544203, 348544, 27133, '<td valign="top">Good work....this scene does suit the challenge.</td>', 'Good work....this scene does suit the challenge.', '2006-06-23 07:04:29.000000', NULL, 1),
(2544210, 349513, 27133, '<td valign="top">This fits the challenge but I would like to see a little more light on the subject as it is a little difficult to see it.</td>', 'This fits the challenge but I would like to see a little more light on the subject as it is a little difficult to see it.', '2006-06-23 07:09:19.000000', NULL, 1),
(2544212, 348087, 27133, '<td valign="top">I can see what you are aiming at and it is well thought out.  I understand you may be getting DNMC....well don''t worry about them.  You know what you are aiming for and that is all that matters.</td>', 'I can see what you are aiming at and it is well thought out.  I understand you may be getting DNMC....well don''t worry about them.  You know what you are aiming for and that is all that matters.', '2006-06-23 07:10:15.000000', NULL, 1),
(2544213, 349127, 51875, '<td valign="top">Great dramatic scene and posture on the model. I also like the low contrast; it adds to the desolation-feel. The only "-" for me is that I''m not sure whether or not the model is smiling; kind of seems to be doing so and that doesn''t reflect desolation towards me at least. Very well done overall though :) 8</td>', 'Great dramatic scene and posture on the model. I also like the low contrast; it adds to the desolation-feel. The only "-" for me is that I''m not sure whether or not the model is smiling; kind of seems to be doing so and that doesn''t reflect desolation towards me at least. Very well done overall though :) 8', '2006-06-23 07:10:26.000000', NULL, 1),
(2544214, 349299, 27133, '<td valign="top">Good angle and crop.  A bit more contrast would make this pop.</td>', 'Good angle and crop.  A bit more contrast would make this pop.', '2006-06-23 07:10:38.000000', NULL, 1),
