(2552843, 349390, 22975, '<td valign="top">I love the point of view on this... great angle, and the photo meets the challenge beautifully.</td>', 'I love the point of view on this... great angle, and the photo meets the challenge beautifully.', '2006-06-25 22:49:08.000000', NULL, 1),
(2552850, 349309, 22975, '<td valign="top">I''m literally choked up.  I <i>was</i> that little girl.  Great job.</td>', 'I''m literally choked up.  I was that little girl.  Great job.', '2006-06-25 22:50:31.000000', NULL, 1),
(2552851, 348508, 35804, '<td valign="top">Love the green and the "ghost"...great crunchy textures and clarity. The processing really fits the mood of the image...very nice.</td>', 'Love the green and the "ghost"...great crunchy textures and clarity. The processing really fits the mood of the image...very nice.', '2006-06-25 22:50:38.000000', NULL, 1),
